/* ==UserStyle==
@name         Tailwind CSS, Responsive Breakpoints
@namespace    USO Archive
@author       adamculpepper
@description  Displays a live, semi-transparent overlay in the bottom-left corner of any webpage showing the current Tailwind CSS responsive breakpoint and screen orientation. As you resize your browser window, the indicator updates in real time across all six breakpoints — Base/Default (<640px), SM (≥640px), MD (≥768px), LG (≥1024px), XL (≥1280px), and 2XL (≥1536px) — plus a second line that toggles between Portrait and Landscape. A handy visual aid for frontend developers building or debugging responsive layouts with Tailwind CSS.
@version      20260716.01
@license      NONE
@preprocessor uso
==/UserStyle== */
html > body:before,
html > body:after {
    position:fixed;
    left:5px;
    z-index:99999999;
    width:auto;
    height:auto;
    padding:5px;
    color:#fff;
    font-size:12px;
    font-family:'Helvetica Neue', Helvetica, Arial, sans-serif;
    background:rgba(56, 189, 248, 0.75);
    opacity:0.50;
    letter-spacing:1px;
    pointer-events:none;
}


html > body:before {
    content: "Base / Default | (<640px)"; /* Default - no prefix */
    bottom:5px;
}


html > body:after {
    content: "Orientation: Portrait";
    bottom:35px;
}

@media (min-width: 640px)  { html > body:before { content: "Small (SM) | (\2265 640px)";}  }      /* Small - sm */
@media (min-width: 768px)  { html > body:before { content: "Medium (MD) | (\2265 768px)";}  }      /* Medium - md */
@media (min-width: 1024px) { html > body:before { content: "Large (LG) | (\2265 1024px)";}  }      /* Large - lg */
@media (min-width: 1280px) { html > body:before { content: "Extra Large (XL) | (\2265 1280px)";}  } /* Extra Large - xl */
@media (min-width: 1536px) { html > body:before { content: "2X Large (2XL) | (\2265 1536px)";} }    /* 2X Large - 2xl */

/* Styles for screens in portrait orientation */
@media screen and (orientation: portrait) {
  html > body:after {
    content: "Orientation: Portrait";
  }
}

/* Styles for screens in landscape orientation */
@media screen and (orientation: landscape) {
  html > body:after {
    content: "Orientation: Landscape";
  }
}
